#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/china_us_negative_comparison_20261007_002'
test ! -L '/data1/home/sunyiq/china_us_negative_comparison_20261007_002'
mkdir '/data1/home/sunyiq/china_us_negative_comparison_20261007_002'
mkdir '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/src' '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/contracts' '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/logs'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/src/analyze_us_saved_results_v2.py'
printf '%s  %s\n' 'ba395c822c1d1e5c5e2d0d5eade0f12cd4ab9ece34056b03e2f1b7735130c7b6' '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/src/analyze_us_saved_results_v2.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/contracts/US_SAVED_RESULTS_CONTRACT_v1.json'
printf '%s  %s\n' '669cc85f7b3cd1352a0ec26d3410d57496a61644de78e93a826bc4c2295f7609' '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/contracts/US_SAVED_RESULTS_CONTRACT_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/us_statistics_v2.sbatch'
printf '%s  %s\n' '3facc1c6b157a8f2dc64aad9b4d70ffd22a6acc36a732b177aea0dd21acc69fa' '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/us_statistics_v2.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/us_statistics_v2.sbatch')
case "$job" in ''|*[!0-9]*) printf 'UNEXPECTED_JOB_RECEIPT\n' >&2; exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/china_us_negative_comparison_20261007_002/job_id.txt'
printf 'US_STATISTICS_ROOT=/data1/home/sunyiq/china_us_negative_comparison_20261007_002\nUS_STATISTICS_JOB_ID=%s\nUS_STATISTICS_SUBMITTED_ONCE\n' "$job"
